/* ===== Phase 11: Medium problems (part 2) ===== */
P(11,{key:'Design E-commerce Store like Amazon',short:'E-commerce',
  lead:'Design an online store: browse and search a catalogue, manage a cart, check out with payment, track orders and inventory, at very high traffic with sales events.',
  more:['Catalogue browsing is read-heavy and cacheable (CDN, caches, search index). Cart is per-user state that must survive across devices. Checkout is where correctness matters: reserve inventory, take payment and create the order without overselling or double charging, usually as a saga with idempotency keys and an outbox. Flash sales concentrate traffic on a few items; queues, reservation holds and pre-allocated stock protect the system.'],
  clarify:[['Scope?','Catalogue, search, cart, checkout, orders, inventory.'],['Scale?','Assume 100 million daily users, 10 million orders a day, 10x peaks on sale days.'],['Inventory accuracy?','No overselling at checkout; product pages may show approximate stock.'],['Sellers?','Mention marketplace sellers briefly.']],
  est:{dau:100e6,writes:0.1,ratio:500,size:5000,years:5,peak:10,wlabel:'orders',rlabel:'page views',unit:'order'},
  build:B(['Catalogue service with search index and caches/CDN | Read-heavy browsing.','Cart service backed by a KV store | Fast, per-user, cross-device.','Inventory service with atomic reservations | Prevent overselling.','Order service with saga (reserve, pay, confirm) and outbox | Correct multi-step checkout.','Payment integration with idempotency keys | No double charges.','Async pipelines: emails, warehouse, analytics | Keep checkout fast.'],['Synchronously calling ten services in checkout with no timeouts | Fragile and slow.','Decrementing stock without a condition | Overselling under concurrency.','Strong consistency for product page stock counts | Unnecessary cost.']),
  takeaway:'Cache and index the catalogue, keep carts in a fast store, and make checkout a careful saga with atomic inventory reservation, idempotent payment and an outbox.',
  pre:['ACID Transactions','Event-Driven Architecture','Idempotency'],
  quiz:[{q:'How do you prevent selling the last item twice?',o:['Check stock in the app then decrement','Atomic conditional decrement (stock > 0) or a reservation with a lock','Eventual consistency'],a:1,why:'Only one transaction can take the last unit.',hint:'Lost update problem.'},
        {q:'Why make the confirmation email asynchronous?',o:['Emails are unimportant','So checkout does not wait on the email provider and survives its outages','To save money'],a:1,why:'Side effects go to queues.',hint:'Who waits?'}],
  terms:[['Reservation','Temporary hold on stock during checkout.'],['Saga','Multi-step transaction with compensations.'],['SKU','Stock keeping unit: one sellable variant.']],
  deep:[{h:'Catalogue and search',ul:['Product data in a document store; search index from CDC.','Caches and CDN for pages and images.','Price and availability fetched fresh at checkout.']},
   {h:'Cart',ul:['KV store keyed by user (and anonymous session, merged on login).','Prices re-validated at checkout.']},
   {h:'Checkout',ul:['Create order PENDING with idempotency key.','Reserve inventory (conditional update, expiry).','Authorise payment; confirm order; release on failure.','Outbox events for warehouse and notifications.']},
   {h:'Flash sales',ul:['Queue or token gate before checkout.','Pre-split inventory into buckets to reduce contention.','Rate limits and bot protection.']}],
  iq:[{q:'Design the checkout flow.',lvl:'Mid',cover:['Steps and services.','Inventory reservation.','Payment and failure handling.'],pitfalls:['No idempotency.']},
   {q:'Design inventory for a flash sale of 10,000 units with 2 million users trying at once.',cover:['Gate traffic with a queue or tokens.','Sharded or bucketed stock counters; atomic decrements in Redis then durable records.','Reservations with timeouts; fairness; bot control.'],pitfalls:['All requests hitting one database row.']},
   {q:'Split a monolithic e-commerce platform into services without disrupting sales.',lvl:'Staff+',cover:['Bounded contexts: catalogue, cart, orders, inventory, payments.','Strangler migration with CDC; data ownership.','Sagas replacing local transactions; observability.','Freeze windows around peak seasons.'],pitfalls:['Big-bang rewrite before peak season.']}]});

P(11,{key:'Design TikTok',short:'TikTok',
  lead:'Design a short-video app: upload short clips, and serve an endless For You feed of videos chosen by a recommendation system, with very fast start times as users swipe.',
  more:['Two halves. The media pipeline is YouTube-like but tuned for short clips: transcode quickly, store, and push to CDN. The feed is driven by recommendations: candidate retrieval (embeddings, trends, follows), ranking by predicted watch time and engagement, and real-time feedback from swipes and watch time. To make swiping instant, the client prefetches the next few videos and the server precomputes batches of recommendations.'],
  clarify:[['Feed type?','Algorithmic For You feed plus Following.'],['Scale?','Assume 1 billion daily users, 50 videos each.'],['Upload volume?','Assume 50 million uploads a day.'],['Latency?','Next video plays instantly on swipe.']],
  est:{dau:1e9,writes:0.05,ratio:1000,size:15e6,years:3,peak:3,wlabel:'uploads',rlabel:'video views',unit:'video (all renditions)'},
  build:B(['Upload and fast transcoding pipeline | Short clips ready in seconds to minutes.','CDN with aggressive caching of trending clips | Massive view volume.','Recommendation service: candidate retrieval + ranking | The product is the feed.','Real-time event stream of watch time and swipes | Fresh signals for ranking.','Client prefetch of the next videos | Instant playback on swipe.','Feature store for user and video features | Fast ranking inputs.'],['Chronological feed only | Not the product.','Ranking with a nightly batch only | Misses real-time interest changes.','Serving videos from origin | Bandwidth.']),
  takeaway:'A fast media pipeline plus CDN, and a recommendation system with candidate retrieval, ranking and real-time feedback, with prefetching on the client.',
  pre:['Design Youtube','Batch vs Stream Processing'],
  quiz:[{q:'How is swiping made to feel instant?',o:['Bigger servers','The client prefetches the next few videos and the server returns batches of recommendations','Lower video quality only'],a:1,why:'The next video is already downloading.',hint:'Before the swipe.'},
        {q:'Why are watch-time events streamed in real time?',o:['For billing','To update interest signals quickly so the feed adapts within a session','To compress videos'],a:1,why:'Freshness of signals drives recommendation quality.',hint:'Feedback loop.'}],
  terms:[['Candidate retrieval','Fast selection of a few thousand possible items.'],['Embedding','Vector representation for similarity search.'],['Feature store','Serves features to models online.']],
  deep:[{h:'Media',ul:['Upload, transcode a small ladder quickly; more renditions later for popular videos.','Moderation pipeline before wide distribution.','CDN push for trending content.']},
   {h:'Recommendations',ul:['Retrieval: embeddings with approximate nearest neighbour search, trends, follows.','Ranking model predicting watch time and interactions.','Re-ranking for diversity and safety.']},
   {h:'Signals',ul:['Client events batched to an event stream.','Streaming features updated within seconds.','Offline training on historical data.']},
   {h:'Cold start',ul:['New users: popular and diverse content, quick learning from swipes.','New videos: small initial audience test, then expand by performance.']}],
  iq:[{q:'Design the For You feed at a high level.',lvl:'Mid',cover:['Retrieval, ranking, serving.','Signals and feedback.','Caching and prefetch.'],pitfalls:['A chronological feed.']},
   {q:'How do you give new videos a fair chance without hurting user experience?',cover:['Exploration traffic with small audiences.','Promote based on early engagement relative to expectations.','Safety review gates.'],pitfalls:['Only showing proven popular videos.']},
   {q:'Design the real-time feature pipeline that feeds the ranking model.',lvl:'Staff+',cover:['Event ingestion at millions per second.','Stream processing to features with windows; feature store online and offline consistency.','Latency budgets; backfills; monitoring for skew.'],pitfalls:['Different feature code online and offline.']}]});

P(11,{key:'Design Shopify',short:'Shopify',
  lead:'Design a multi-tenant e-commerce platform: millions of merchants each get their own storefront, products, checkout and admin, sharing infrastructure, with some merchants running huge flash sales.',
  more:['Multi-tenancy is the theme. Tenants are grouped into isolated shards or "pods" (each with its own database), so one merchant\'s flash sale does not hurt others and failures are contained. Storefronts are heavily cached; checkout is the critical path with inventory and payment correctness. Big merchants may get dedicated capacity; tenant routing maps each shop domain to its pod.'],
  clarify:[['Tenants?','Millions of shops, from tiny to very large.'],['Custom domains and themes?','Yes.'],['Peak events?','Black Friday and individual flash sales.'],['Apps and APIs for merchants?','Yes, with rate limits.']],
  est:{dau:50e6,writes:0.1,ratio:300,size:5000,years:5,peak:10,wlabel:'orders',rlabel:'storefront views',unit:'order'},
  build:B(['Tenant routing from domain to pod | Each shop served by its home pod.','Pods: isolated groups of shops with their own databases | Blast radius and noisy-neighbour control.','Storefront rendering with heavy caching and CDN | Mostly read traffic.','Checkout service with inventory reservations and idempotent payments | Correctness under spikes.','Merchant API with per-app rate limits | Protect the platform.','Shop migration tooling between pods | Rebalance large merchants.'],['One shared database for all merchants | Noisy neighbours and a huge blast radius.','A separate deployment per merchant | Operationally unmanageable at millions.','No per-tenant rate limiting | One app can overload a pod.']),
  takeaway:'Group tenants into isolated pods, route by domain, cache storefronts, protect checkout, rate-limit per tenant and app, and be able to move tenants between pods.',
  pre:['Design E-commerce Store like Amazon','Database Sharding','Rate limiting'],
  quiz:[{q:'Why group merchants into pods?',o:['To simplify billing','To isolate load and failures so one merchant cannot take down everyone','To save storage'],a:1,why:'Pods limit blast radius and noisy neighbours.',hint:'Isolation.'},
        {q:'A huge merchant outgrows its pod. What do you do?',o:['Nothing','Move the shop to a less loaded or dedicated pod with migration tooling','Delete old orders'],a:1,why:'Rebalancing by tenant is the scaling lever.',hint:'Move the tenant.'}],
  terms:[['Multi-tenancy','Many customers sharing one system.'],['Pod','Isolated unit of infrastructure serving a set of tenants.'],['Noisy neighbour','A tenant whose load harms others.']],
  deep:[{h:'Tenant model',ul:['Every table has shop_id; queries always scoped by it.','Pods: database plus caches and workers for a set of shops.','Routing table from domain to shop to pod.']},
   {h:'Storefront',ul:['Theme rendering with caching per shop; CDN for assets.','Edge caching of product pages; invalidation on change.']},
   {h:'Flash sales',ul:['Inventory reservations with contention control.','Checkout queues for big launches.','Bot protection.']},
   {h:'Platform APIs',ul:['Per-app, per-shop rate limits (leaky bucket).','Webhooks to apps with retries.','GraphQL with query cost limits.']}],
  iq:[{q:'Design data isolation between merchants.',lvl:'Mid',cover:['Tenant id on all data; enforced in queries.','Pods; access control.','Testing for leaks.'],pitfalls:['Relying on developers remembering a WHERE clause without safeguards.']},
   {q:'Design shop migration between pods with no downtime.',cover:['Copy data with CDC; catch up; brief write pause; switch routing.','Verify; rollback plan.','Background jobs and caches handled.'],pitfalls:['Long downtime.']},
   {q:'Prepare the platform for Black Friday, when total traffic grows 10x and some shops grow 100x.',lvl:'Staff+',cover:['Capacity planning per pod; isolate the biggest merchants.','Load tests; caching; checkout queues.','Feature freezes; incident readiness; degradation plans.'],pitfalls:['Uniform scaling without considering hot tenants.']}]});

P(11,{key:'Design Airbnb',short:'Airbnb',
  lead:'Design a home-rental marketplace: hosts list homes with calendars and prices, guests search by location and dates, book stays without double booking, and pay, with payouts to hosts later.',
  more:['Search combines geography (geospatial index), date availability, price and filters, so listings and calendars are indexed in a search engine and refreshed from the source of truth. Booking must be consistent: reserve the specific dates atomically, then take payment, with holds that expire. Payments involve collecting from guests and paying hosts after check-in, in many currencies, without double payments (Airbnb wrote about idempotency for exactly this).'],
  clarify:[['Scope?','Search, listing details, booking, payments; reviews briefly.'],['Scale?','Assume 7 million listings, 100 million searches a day.'],['Instant book or request to book?','Both.'],['Double booking tolerance?','None.']],
  est:{dau:30e6,writes:0.05,ratio:500,size:5000,years:5,peak:3,wlabel:'bookings',rlabel:'searches and views',unit:'booking'},
  build:B(['Search index with geo, date availability and filters | Fast map and date search.','Listing and calendar store (source of truth) | Accurate availability.','Booking service with atomic date reservation | No double booking.','Payment service with idempotency, holds and delayed payouts | Correct money flow.','CDC from calendars to the search index | Keep search fresh.','Caching of listing pages and images via CDN | Read-heavy traffic.'],['Querying the relational calendar for every map search | Too slow.','Booking by checking availability then inserting without a lock or constraint | Double bookings.','Paying hosts immediately at booking | Cancellations and fraud.']),
  takeaway:'Search from an index refreshed from the source of truth, book dates atomically with constraints or locks, and run payments as idempotent, staged flows.',
  pre:['Design Ticket Booking System like BookMyShow','Design Payment System','Change Data Capture (CDC)'],
  quiz:[{q:'How do you prevent two guests booking the same night?',o:['Check availability in search results','Reserve the dates in the source of truth atomically (unique constraint per listing-night or a row lock)','Ask the host'],a:1,why:'The search index may be stale; the booking must be atomic.',hint:'Where is the truth?'},
        {q:'Why can search show a home as available when it was just booked?',o:['A bug always','The search index is updated asynchronously from the source of truth','The guest is lying'],a:1,why:'Eventual consistency in search; the booking step re-checks.',hint:'Two copies.'}],
  terms:[['Availability calendar','Per-night status of a listing.'],['Hold','Temporary reservation pending payment.'],['Payout','Payment to the host.']],
  deep:[{h:'Search',ul:['Index listings by location (geo shapes), price, amenities.','Availability as date ranges or bitsets per listing in the index.','Ranking by relevance, price, quality.']},
   {h:'Booking',ul:['Hold: insert listing-night rows with a unique constraint, or conditional update.','Payment authorisation; confirm; release on failure or timeout.','Request-to-book flows with host approval deadlines.']},
   {h:'Payments',ul:['Charge guest; hold funds; pay host after check-in.','Idempotency keys across services; ledger entries.','Currency conversion and refunds.']},
   {h:'Freshness and scale',ul:['CDC from calendars to the index; seconds of lag.','Re-check availability at booking.','Shard bookings by listing.']}],
  iq:[{q:'Design the booking flow without double booking.',lvl:'Mid',cover:['Atomic reservation of nights.','Holds and timeouts.','Payment integration.'],pitfalls:['Trusting search results.']},
   {q:'Design search by map area and dates for 7 million listings.',cover:['Geo index and availability representation.','Filters and ranking.','Freshness via CDC; caching.'],pitfalls:['SQL joins on the calendar per search.']},
   {q:'Design the payments flow so neither guests nor hosts are ever paid or charged twice across retries and service failures.',lvl:'Staff+',cover:['Idempotency keys at every hop; ledger as source of truth.','Saga with compensations; reconciliation with processors.','Delayed payouts and refunds; audits.'],pitfalls:['Retrying payment calls without idempotency.']}]});

P(11,{key:'Design Rate Limiter',short:'Rate Limiter',
  lead:'Design a rate limiter that caps how many requests a client can make (for example 100 per minute per API key), enforced consistently across many gateway servers with very low added latency.',
  more:['The algorithm (token bucket, leaky bucket, fixed window, sliding window log or counter) is covered in the Rate limiting lesson; the system design question is where counters live. A shared store such as Redis with atomic operations (Lua scripts or INCR with expiry) gives a consistent limit across servers at the cost of a network hop; local counters are faster but approximate. Rules come from configuration; responses use 429 with Retry-After headers. Decide what happens if the limiter store is down: fail open or closed.'],
  clarify:[['Limit by what?','API key, user, IP, endpoint.'],['Where enforced?','In the API gateway.'],['Accuracy?','Approximate is fine; a few percent over is acceptable.'],['Scale?','Assume 1 million requests per second.']],
  est:{dau:10e6,writes:8000,ratio:1,size:100,years:0,peak:3,wlabel:'requests',rlabel:'counter checks',unit:'counter'},
  build:B(['Gateway middleware calling the limiter | Enforce before backends.','Shared counter store (Redis) with atomic scripts | Consistent counts across servers.','Algorithm such as token bucket or sliding window counter | Smooth and accurate enough.','Rule configuration service | Limits per client and endpoint.','429 responses with Retry-After and rate headers | Clients can back off.','Local fallback limits if the store is unavailable | Fail-open or fail-closed policy.'],['A relational database write per request | Too slow.','Fixed windows only, with no handling of boundary bursts | Clients can double their rate at boundaries.','Per-server limits with no coordination for strict global limits | Limits multiply by server count.']),
  takeaway:'Pick an algorithm, keep counters in a fast shared store with atomic updates, enforce at the gateway, return 429 with retry hints, and decide fail-open vs fail-closed.',
  pre:['Rate limiting','Distributed Caching'],
  quiz:[{q:'Why use a Lua script or atomic command in Redis?',o:['Speed of Lua','So read-modify-write of the counter is atomic and concurrent requests do not race','Redis requires it'],a:1,why:'Without atomicity two servers can both read the same count.',hint:'Lost updates.'},
        {q:'The limiter store is down. What is a common choice for a public API?',o:['Reject everything','Fail open with local approximate limits, while alerting','Restart all gateways'],a:1,why:'Blocking all traffic turns a limiter outage into a full outage; local limits still protect somewhat.',hint:'Availability vs protection.'}],
  terms:[['429','HTTP Too Many Requests.'],['Sliding window counter','Weighted blend of current and previous window counts.'],['Fail open','Allow traffic when the control fails.']],
  deep:[{h:'Algorithms',ul:['Token bucket: bursts up to capacity, average refill rate.','Sliding window counter: low memory, good accuracy.','Sliding log: exact, memory heavy.']},
   {h:'Distributed counters',ul:['Redis keyed by client and window; TTL.','Lua script for check and increment.','Shard Redis by key; replicas for availability.']},
   {h:'Latency and accuracy',ul:['Local token buckets synced periodically for lower latency.','Batch increments; accept small overshoot.','Place limiter close to gateways.']},
   {h:'Operations',ul:['Rules hot-reloaded; per-tenant overrides.','Metrics on limited requests; alerts.','Different limits for burst protection and quotas.']}],
  iq:[{q:'Implement a token bucket rate limiter for one server.',lvl:'Mid',cover:['Tokens, capacity, refill on access with timestamps.','Thread safety.'],pitfalls:['A timer thread per client.']},
   {q:'Design a distributed rate limiter for 1 million requests per second across 200 gateways.',cover:['Redis cluster with atomic scripts; sharding.','Latency budget; local caching of decisions.','Failure policy.'],pitfalls:['A database row per client.']},
   {q:'Design global rate limits for a multi-region API with a 100 ms cross-region latency.',lvl:'Staff+',cover:['Per-region budgets that sum to the global limit; periodic rebalancing.','Accept approximate enforcement; asynchronous sync.','Strict limits only where required.'],pitfalls:['Synchronous cross-region checks per request.']}]});

P(11,{key:'Design Distributed Message Queue like Kafka',short:'Kafka',
  lead:'Design a distributed log-based message broker: producers append messages to topics, consumers read them at their own pace from offsets, with high throughput, durability through replication, and ordering within partitions.',
  more:['Topics are split into partitions; each partition is an append-only log stored in segment files on disk and replicated to several brokers. One replica leads each partition; followers copy it, and a write is acknowledged when in-sync replicas have it (acks=all). Consumers in a group divide partitions among themselves and commit offsets. Sequential disk writes, batching, compression and zero-copy reads make it fast. Controller metadata (partition leaders, membership) lives in a consensus system (KRaft or ZooKeeper).'],
  clarify:[['Delivery guarantees?','At least once by default; exactly-once within the system optional.'],['Ordering?','Per partition.'],['Retention?','Days, or compacted by key.'],['Throughput?','Millions of messages per second.']],
  est:{dau:1e6,writes:100000,ratio:3,size:1000,years:0.02,peak:3,wlabel:'messages',rlabel:'consumer reads',unit:'message'},
  build:B(['Partitioned append-only logs in segment files | Sequential I/O and ordering per partition.','Leader-follower replication with in-sync replica set | Durability without blocking on slow replicas.','Consumer groups with committed offsets | Scale consumption and resume after failures.','Controller with consensus for metadata and leader election | Correct failover.','Batching, compression, zero-copy transfer | High throughput.','Retention by time/size and log compaction | Bounded storage and latest-value topics.'],['Deleting messages when consumed | Prevents replay and multiple groups.','A global order across all messages | Kills parallelism.','Random disk writes per message | Slow.']),
  takeaway:'Partitioned, replicated append-only logs with consumer-managed offsets, a consensus-backed controller, and batching for throughput.',
  pre:['Message Brokers','Database Replication','Consensus Algorithms'],
  quiz:[{q:'Why is Kafka fast despite writing to disk?',o:['It uses RAM only','Sequential appends, batching and OS page cache with zero-copy sends','It skips replication'],a:1,why:'Sequential I/O and batching are very efficient.',hint:'Access pattern.'},
        {q:'What limits the parallelism of a consumer group?',o:['Number of topics','Number of partitions','Number of brokers'],a:1,why:'Each partition is consumed by at most one member of a group.',hint:'Unit of parallelism.'}],
  terms:[['Partition','Ordered log shard of a topic.'],['ISR','In-sync replicas.'],['Log compaction','Keep only the latest message per key.']],
  deep:[{h:'Storage',ul:['Segments with index files mapping offset to position.','Retention deletes old segments; compaction rewrites by key.','Page cache serves recent reads.']},
   {h:'Replication',ul:['Leader per partition; followers fetch.','acks=all with min in-sync replicas for durability.','Unclean leader election off for critical data.']},
   {h:'Consumers',ul:['Group coordinator assigns partitions; rebalances on membership change.','Offsets committed to an internal topic.','Lag monitoring.']},
   {h:'Producers and semantics',ul:['Partition by key for ordering.','Idempotent producers prevent duplicates on retry.','Transactions for exactly-once read-process-write.']}],
  iq:[{q:'Explain topics, partitions, offsets and consumer groups.',lvl:'Mid',cover:['Definitions and relationships.','Ordering scope.','Scaling consumers.'],pitfalls:['Global ordering claims.']},
   {q:'Design replication and failover for partitions.',cover:['Leader, followers, ISR.','acks settings; min ISR.','Leader election via controller; data loss scenarios.'],pitfalls:['Ignoring unclean election.']},
   {q:'Design a multi-region event backbone on Kafka-like brokers.',lvl:'Staff+',cover:['Regional clusters; mirroring for cross-region consumers.','Ordering and duplicates across regions.','Failover of producers and offset translation.','Cost of cross-region traffic.'],pitfalls:['One cluster stretched across distant regions.']}]});

P(11,{key:'Design Flight Booking System',short:'Flight Booking',
  lead:'Design a flight booking site: search flights across airlines, show prices and seat availability, hold a seat, take payment and issue a ticket, while airline inventory systems remain the source of truth.',
  more:['Search is the expensive part: combining routes, dates and fares across many airlines and global distribution systems (GDS). Results are cached aggressively because fares change but not every second, and availability is re-checked before booking. Booking is a multi-step, multi-party process: hold the seat with the airline (time-limited), take payment, issue the ticket; failures need compensations (release the hold, refund) and reconciliation.'],
  clarify:[['Own inventory or aggregator?','Aggregator over airlines and GDSs.'],['Scale?','Assume 10 million searches a day, 200,000 bookings.'],['Seat selection?','Yes, after booking.'],['Price changes between search and booking?','Must re-quote and tell the user.']],
  est:{dau:5e6,writes:0.04,ratio:50,size:3000,years:5,peak:5,wlabel:'bookings',rlabel:'searches',unit:'booking'},
  build:B(['Search aggregator querying airlines/GDS in parallel with timeouts | Results from many sources quickly.','Fare and availability cache with short TTLs | Cut expensive upstream calls.','Booking saga: hold seat, pay, issue ticket | Multi-party transaction with compensations.','Idempotency keys for supplier and payment calls | Retries without duplicates.','Re-pricing check before payment | Prices change.','Reconciliation with airlines | Catch mismatches.'],['Trusting cached prices at payment | Users charged wrong amounts.','Two-phase commit with airlines | Not available across external systems.','Synchronous search across all airlines with no timeouts | One slow supplier ruins latency.']),
  takeaway:'Parallel, cached, time-bounded searches across suppliers; re-check before booking; and a saga with holds, idempotent calls, compensations and reconciliation.',
  pre:['Design Ticket Booking System like BookMyShow','Event-Driven Architecture','Circuit Breaker'],
  quiz:[{q:'A fare changed between search and checkout. What should happen?',o:['Charge the old price','Re-quote with the airline and show the new price before payment','Cancel silently'],a:1,why:'Cached search prices are not authoritative.',hint:'Source of truth.'},
        {q:'Payment succeeded but ticket issuance failed. What next?',o:['Ignore','Retry issuance; if it cannot succeed, release the hold and refund (compensation)','Charge again'],a:1,why:'Saga compensations restore a consistent state.',hint:'Undo steps.'}],
  terms:[['GDS','Global distribution system for airline inventory.'],['PNR','Passenger name record: the booking at the airline.'],['Hold','Seat reserved for a limited time.']],
  deep:[{h:'Search',ul:['Fan out to suppliers with deadlines; return partial results.','Cache popular routes; precompute fare tables.','Rank by price, duration, stops.']},
   {h:'Booking',ul:['Create booking PENDING; request hold (PNR).','Re-price; authorise payment; issue ticket; capture.','Compensate on failure; notify user.']},
   {h:'Reliability',ul:['Circuit breakers per supplier.','Idempotent supplier calls where supported; status queries otherwise.','Daily reconciliation of tickets and payments.']},
   {h:'Data',ul:['Bookings in a relational database.','Search logs for analytics and caching.','PII protection.']}],
  iq:[{q:'Design flight search across 50 airlines.',lvl:'Mid',cover:['Parallel calls, timeouts, caching.','Merging and ranking.'],pitfalls:['Sequential supplier calls.']},
   {q:'Design the booking saga and its compensations.',cover:['Steps and states.','Failure at each step.','Idempotency and reconciliation.'],pitfalls:['Assuming distributed transactions.']},
   {q:'Search costs (per supplier call fees) are exploding. Redesign to cut them by 70% without hurting conversion.',lvl:'Staff+',cover:['Smarter caching with demand prediction; precomputed fare grids.','Look-to-book ratio controls; rate limiting bots.','Re-validate only for selected itineraries.','Measure conversion impact with experiments.'],pitfalls:['Simply caching longer and selling stale fares.']}]});

P(11,{key:'Design Online Code Editor',short:'Code Editor',
  lead:'Design an online code editor and runner (like LeetCode or Replit): users write code in the browser, run it against tests, and see output, safely, for many languages and many concurrent users.',
  more:['Running untrusted code is the central risk. Each run executes in an isolated sandbox (containers with gVisor, Firecracker microVMs) with CPU, memory, time, network and filesystem limits. Submissions go to a queue; a pool of warm sandboxes per language picks them up, runs the tests and returns results. Collaborative editing (if in scope) adds operational transformation or CRDTs over WebSockets.'],
  clarify:[['Run or also collaborate?','Run and judge; collaboration optional.'],['Languages?','About 20.'],['Scale?','Assume 5,000 runs per second at contest peaks.'],['Time limits?','A few seconds per run.']],
  est:{dau:5e6,writes:20,ratio:1,size:5000,years:1,peak:10,wlabel:'code runs',rlabel:'result reads',unit:'submission'},
  build:B(['Submission API and queue | Absorb contest spikes.','Sandboxed executors (microVMs or gVisor containers) with resource limits | Run untrusted code safely.','Warm pools per language | Low start latency.','Test runner comparing outputs | Judge correctness.','Result store and push of results to the client | Show output quickly.','Abuse controls (no network, rate limits) | Prevent crypto mining and attacks.'],['Running user code directly on API servers | Remote code execution risk.','A new VM booted per run without pooling | Slow.','Unlimited CPU and network for runs | Abuse.']),
  takeaway:'Queue submissions, run them in strongly isolated, resource-limited, pre-warmed sandboxes, and return results asynchronously.',
  pre:['Message Queues','Serverless Architecture'],
  quiz:[{q:'What is the biggest risk in an online code runner?',o:['Slow typing','Executing untrusted code that could escape, attack the network or use unlimited resources','Syntax highlighting'],a:1,why:'Isolation and limits are mandatory.',hint:'Whose code runs?'},
        {q:'How do you keep run latency low despite strong isolation?',o:['Turn off isolation','Keep warm pools of sandboxes per language','Use bigger machines only'],a:1,why:'Starting a sandbox is the slow part.',hint:'Pre-start.'}],
  terms:[['Sandbox','Restricted environment for untrusted code.'],['Firecracker','Lightweight microVM technology.'],['Judge','Component that checks outputs against tests.']],
  deep:[{h:'Execution',ul:['Sandbox per run; read-only base image; tmpfs workspace.','cgroups for CPU and memory; time limits; no network by default.','Clean up or recycle sandboxes safely.']},
   {h:'Pipeline',ul:['Submit, queue, executor picks, compile, run tests, store results.','Results pushed via WebSocket or polled.','Priority queues for interactive runs vs contest judging.']},
   {h:'Scaling',ul:['Autoscale executors on queue depth.','Pre-scale for contests.','Cache compiled artefacts for test inputs.']},
   {h:'Collaboration (optional)',ul:['OT or CRDT documents over WebSockets.','Presence and cursors.','Persist snapshots and operations.']}],
  iq:[{q:'Design the run-code flow.',lvl:'Mid',cover:['API, queue, executors, results.','Limits and timeouts.'],pitfalls:['Running on API servers.']},
   {q:'Harden the sandbox against malicious code.',cover:['Kernel isolation (microVMs, gVisor), seccomp, no network, resource limits.','Separate hosts for untrusted work.','Monitoring for escapes and abuse.'],pitfalls:['Plain Docker with default settings as the only barrier.']},
   {q:'A programming contest brings 200,000 users submitting in the same 10 minutes. Plan for it.',lvl:'Staff+',cover:['Capacity estimate; pre-warm pools.','Queue with fairness; priority for contest judging.','Degrade non-contest features; status page.','Load test beforehand.'],pitfalls:['Reactive autoscaling only.']}]});

P(11,{key:'Design an Analytics Platform (Metrics & Logging)',short:'Metrics & Logging',
  lead:'Design a platform that collects metrics and logs from thousands of services, stores them efficiently, and lets engineers query dashboards and set alerts. Real reports include "design a logger system for a pool of apps" (Meta, Staff) and "a metrics API with graphs over time ranges" (LinkedIn).',
  more:['Metrics and logs are different shapes. Metrics are numeric time series (name, tags, timestamp, value) stored in a time-series database with compression and downsampling. Logs are text events stored in a log store with an index (or columnar storage) for search. Both flow through agents, then a durable buffer (Kafka) so spikes and outages do not lose data, then processors. High-cardinality tags, retention tiers, and alert evaluation are the main deep dives.'],
  clarify:[['Metrics, logs, or both?','Both.'],['Scale?','Assume 10,000 hosts, 10 million metric points per second, 2 TB of logs a day.'],['Query latency?','Dashboards in seconds.'],['Retention?','Raw 15 days, downsampled for a year.']],
  est:{dau:10000,writes:8.6e7,ratio:0.01,size:20,years:1,peak:2,wlabel:'metric points',rlabel:'query reads',unit:'data point'},
  build:B(['Agents on hosts batching and compressing | Efficient collection.','Durable ingestion buffer (Kafka) | Absorb spikes and backend outages.','Time-series DB with compression and downsampling | Efficient metric storage and queries.','Log store with indexing or columnar search | Search logs by fields and text.','Alerting engine evaluating rules on streams | Timely alerts.','Query and dashboard service with caching | Fast graphs.'],['Writing every log line to a relational database | Too slow and expensive.','Unbounded tag cardinality (user id as a metric tag) | Explodes series count.','Synchronous writes from apps to storage | Apps slow down when storage does.']),
  takeaway:'Collect through agents into a durable buffer, store metrics in a time-series database and logs in a searchable store, control cardinality and retention, and evaluate alerts on streams.',
  pre:['Batch vs Stream Processing','Message Brokers','Database Partitioning'],
  quiz:[{q:'Why is high cardinality dangerous for metrics?',o:['It is not','Each unique tag combination is a new series; tags like user id create millions of series and overwhelm storage and queries','It slows the network only'],a:1,why:'Cardinality drives memory and index size.',hint:'Count unique series.'},
        {q:'Why put Kafka between agents and storage?',o:['To encrypt','To buffer spikes and outages so data is not lost or pushed back onto apps','For dashboards'],a:1,why:'Decouples producers from storage health.',hint:'Load leveling.'}],
  terms:[['Time series','Sequence of values over time for one metric and tag set.'],['Downsampling','Reducing resolution of old data.'],['Cardinality','Number of distinct series.']],
  deep:[{h:'Metrics path',ul:['Agents scrape or receive; pre-aggregate.','Ingest via Kafka; time-series DB partitioned by series and time.','Gorilla-style compression; downsampling jobs.']},
   {h:'Logs path',ul:['Agents tail files; parse; batch.','Kafka; indexers into a search store or columnar store.','Hot, warm and cold tiers; sampling of noisy logs.']},
   {h:'Queries and alerts',ul:['Query engine merges shards; caches dashboard queries.','Alert rules evaluated on streaming data or frequent queries.','Deduplication and routing of alerts.']},
   {h:'Multi-tenancy and cost',ul:['Per-team quotas on series and log volume.','Cost dashboards per team.','Retention policies by data class.']}],
  iq:[{q:'Design a logging system for a pool of apps.',lvl:'Mid',cover:['Agents, buffer, storage, search.','Retention.','Structured logs.'],pitfalls:['Apps writing directly to a database.']},
   {q:'Design a metrics API that stores counts and lets users graph any time range quickly.',cover:['Time-series storage with rollups (1 min, 1 h, 1 day).','Query picks the resolution by range.','Caching; cardinality control.'],pitfalls:['Scanning raw points for a one-year graph.']},
   {q:'The observability bill has tripled in a year. Design controls without losing what engineers need in incidents.',lvl:'Staff+',cover:['Cardinality limits and linting; per-team budgets.','Log sampling and tiering; shorter raw retention.','Tail-based trace sampling.','Measure query patterns to keep useful data.'],pitfalls:['Cutting retention blindly.']}]});

P(11,{key:'Design Payment System',short:'Payment System',
  lead:'Design the payment system of an e-commerce company: accept card payments through external processors, never charge twice, keep an accurate ledger, pay sellers, and reconcile with banks. Stripe and Airbnb have both written about how hard "exactly once" is here.',
  more:['A payment service creates a payment intent with an idempotency key, calls the processor (Stripe, Adyen) with that key, and records the outcome. Uncertain outcomes (timeouts) are resolved by querying the processor, not by retrying blindly. Every money movement is recorded in a double-entry ledger (each transaction debits one account and credits another, so totals always balance). Webhooks from processors update status; nightly reconciliation compares the ledger with processor and bank reports.'],
  clarify:[['Pay-in only or pay-out too?','Both: charge buyers, pay sellers.'],['Scale?','Assume 1 million payments a day.'],['Processors?','External processors; we do not store raw card numbers.'],['Currencies?','Multiple.']],
  est:{dau:1e6,writes:1,ratio:5,size:2000,years:7,peak:5,wlabel:'payments',rlabel:'status reads',unit:'payment + ledger entries'},
  build:B(['Payment service with idempotency keys and a state machine | No double charges, clear states.','Processor integration (tokenised cards, no raw PANs stored) | PCI scope reduction.','Double-entry ledger | Accurate, auditable balances.','Webhook handler (verified, idempotent) | Asynchronous status updates.','Retry with status queries for unknown outcomes | Resolve timeouts safely.','Reconciliation jobs against processor and bank reports | Catch every discrepancy.'],['Retrying charges blindly on timeout | Double charges.','Storing raw card numbers in your database | Huge PCI scope and risk.','Updating a single balance column with no ledger | No audit trail.']),
  takeaway:'Idempotent payment intents with explicit states, tokenised processor calls, a double-entry ledger, verified webhooks, and daily reconciliation.',
  pre:['Idempotency','ACID Transactions','Webhooks'],
  quiz:[{q:'The call to the processor times out. What should the payment service do?',o:['Charge again','Query the processor for the payment by idempotency key or id, then decide','Mark as failed and refund'],a:1,why:'The charge may have succeeded; find out first.',hint:'Unknown, not failed.'},
        {q:'Why use a double-entry ledger?',o:['It is faster','Every movement has matching debits and credits, so errors show up as imbalances and history is auditable','Regulators forbid single entries'],a:1,why:'Balance is derived from entries that always sum to zero.',hint:'Two sides.'}],
  terms:[['Payment intent','Record of an attempt to collect a payment.'],['Double-entry','Each transaction debits and credits accounts equally.'],['Reconciliation','Matching internal records with external statements.']],
  deep:[{h:'Pay-in flow',ul:['Client tokenises card with the processor SDK.','Create payment (PENDING) with idempotency key; call processor with the same key.','Record result; ledger entries on success; emit event.']},
   {h:'States and failures',ul:['States: created, authorised, captured, failed, refunded, unknown.','Unknown resolved by polling or webhooks.','Timeouts never trigger a new charge.']},
   {h:'Ledger',ul:['Immutable entries; accounts for buyers, sellers, fees, processor.','Balances derived or cached with versioning.','Audit and reporting.']},
   {h:'Pay-out and reconciliation',ul:['Scheduled payouts after holds; batch bank transfers.','Daily reconciliation of ledger vs processor vs bank.','Discrepancy queue for humans.']}],
  iq:[{q:'Design charging a customer once, even with retries.',lvl:'Mid',cover:['Idempotency keys end to end.','State machine; unknown outcomes.'],pitfalls:['Retrying without keys.']},
   {q:'Design the ledger data model and how balances are computed.',cover:['Accounts, transactions, entries; sums to zero.','Derived balances; concurrency on balance updates.','Corrections as new entries, never edits.'],pitfalls:['Mutable balance column only.']},
   {q:'Reconciliation shows 0.1% of payments mismatched daily. Design the investigation and the fixes.',lvl:'Staff+',cover:['Categorise mismatches (timing, duplicates, missing webhooks, currency).','Automated resolution for known classes; manual queue for others.','Root causes: idempotency gaps, webhook loss, clock and cut-off differences.','Metrics and SLAs on reconciliation.'],pitfalls:['Treating it as acceptable noise.']}]});

P(11,{key:'Design a Digital Wallet',short:'Digital Wallet',
  lead:'Design a digital wallet (like PayPal or Venmo balances): users top up, hold a balance, and transfer money to each other instantly, with strong correctness at high throughput.',
  more:['Each transfer debits one wallet and credits another, and must never lose or create money. Within one database this is a transaction; at scale wallets are sharded, so a transfer between shards needs a distributed protocol: two-phase commit, Try-Confirm/Cancel, or a saga with a ledger and compensations. Event sourcing fits well: the ledger of transfers is the source of truth and balances are derived and cached. Idempotency and reconciliation complete the design.'],
  clarify:[['Operations?','Top-up, transfer, withdraw, balance.'],['Scale?','Assume 1 million transfers per second at peak (book example) or far less in practice.'],['Consistency?','Strong: no negative balances, exact totals.'],['Cross-currency?','Out of scope.']],
  est:{dau:50e6,writes:2,ratio:5,size:500,years:7,peak:5,wlabel:'transfers',rlabel:'balance reads',unit:'ledger entry'},
  build:B(['Ledger of transfers as the source of truth | Auditable, rebuildable balances.','Wallets sharded by user | Scale throughput.','Cross-shard transfer protocol (TC/C or saga with reservations) | Atomic effect across shards.','Idempotency keys per transfer | Safe retries.','Balance cache derived from the ledger | Fast reads.','Reconciliation and invariants (total balance conserved) | Detect bugs.'],['Updating two balance rows on different shards without coordination | Money can vanish or double.','Eventual consistency allowing negative balances | Overdrafts and fraud.','No ledger, only balances | No audit.']),
  takeaway:'Keep a ledger as the truth, shard wallets, coordinate cross-shard transfers with TC/C or sagas plus reservations, make every transfer idempotent, and continuously check that money is conserved.',
  pre:['Design Payment System','Event-Driven Architecture','Database Sharding'],
  quiz:[{q:'How does Try-Confirm/Cancel move money across two shards?',o:['One update','Try reserves funds on both sides, then Confirm applies both or Cancel releases both','It does not'],a:1,why:'Reservations make the final step safe to complete or undo.',hint:'Reserve first.'},
        {q:'What invariant should reconciliation check?',o:['Number of users','The sum of all balances equals total deposits minus withdrawals','Server uptime'],a:1,why:'Transfers move money but never create it.',hint:'Conservation.'}],
  terms:[['TC/C','Try-Confirm/Cancel distributed transaction pattern.'],['Ledger','Append-only record of money movements.'],['Invariant','A condition that must always hold.']],
  deep:[{h:'Data model',ul:['accounts(id, owner, currency).','ledger_entries(transfer_id, account, amount, created) append-only.','balances(account, amount, version) derived and cached.']},
   {h:'Transfers',ul:['Same shard: one local transaction (debit, credit, entries).','Cross shard: TC/C or saga with holds; transfer state machine.','Idempotency by transfer id.']},
   {h:'Event sourcing option',ul:['Commands validated against current state; events appended.','State machines replay events; snapshots.','Deterministic processing enables replay and audit.']},
   {h:'Safety',ul:['Fraud checks and limits.','Continuous reconciliation and alerts on invariant violation.','Strict access controls and audit logs.']}],
  iq:[{q:'Design a transfer between two wallets in one database.',lvl:'Mid',cover:['Transaction with conditional debit (balance >= amount).','Ledger entries; idempotency.'],pitfalls:['Reading and writing balances without locks.']},
   {q:'Design cross-shard transfers.',cover:['TC/C or saga; reservations; states.','Failure at each step; recovery.','Idempotency and ordering per account.'],pitfalls:['Two independent updates.']},
   {q:'Design a wallet that handles 1 million transfers per second with auditability.',lvl:'Staff+',cover:['Partition by account; event-sourced state machines per partition.','Deterministic processing; replicated logs (Raft).','Snapshots, replay, reconciliation.','Hot accounts (merchants) handled with sub-accounts.'],pitfalls:['A single relational primary.']}]});

/* Extras from the book notes */
P(11,{key:'Design Nearby Friends',short:'Nearby Friends',
  lead:'Show users which of their friends are nearby right now, updating as people move. Location updates arrive every few seconds from millions of phones.',
  more:['Each active user sends location periodically over a WebSocket. The server stores the latest location in a cache with a TTL and publishes it to a channel for that user. Each user\'s connection subscribes to their friends\' channels and computes distance, pushing updates when friends are within range. Redis pub/sub (sharded) or a similar system carries the fan-out; location history goes to a database for analytics if needed.'],
  clarify:[['Range?','Within 5 miles.'],['Update frequency?','Every 30 seconds.'],['Scale?','Assume 10 million concurrent active users, 400 friends each on average.'],['History?','Optional.']],
  est:{dau:10e6,writes:2880,ratio:400,size:50,years:0,peak:2,wlabel:'location updates',rlabel:'friend deliveries',unit:'location'},
  build:B(['WebSocket servers for location updates and pushes | Real-time two-way.','Location cache with TTL (latest per user) | Fast lookup of current positions.','Pub/sub channel per user (sharded) | Fan-out updates to subscribed friends.','Distance filtering on the subscriber\'s server | Push only nearby friends.','Friend list service | Who to subscribe to.','Optional location history store | Analytics.'],['Writing every location to a relational table and polling | Too slow and heavy.','Broadcasting each update to all online users | Massive waste.','Geospatial search across all users for each update | Unnecessary: only friends matter.']),
  takeaway:'Keep latest locations in a cache, publish updates per user, subscribe each connection to its friends, filter by distance before pushing.',
  pre:['WebSockets','Pub/Sub','Design Location Based Service like Yelp'],
  quiz:[{q:'Why use a channel per user rather than a geospatial query?',o:['Channels are cheaper to store','The question is about friends only, so subscribing to friends\' updates is far cheaper than searching all users','Geospatial indexes do not exist'],a:1,why:'Scope the work to the friend graph.',hint:'Who are we looking for?'},
        {q:'Why store locations with a TTL?',o:['To save money','Stale locations of inactive users should disappear automatically','Redis requires it'],a:1,why:'Inactive users drop out without cleanup jobs.',hint:'Old data.'}],
  terms:[['Pub/sub channel','Named stream subscribers listen to.'],['TTL','Time to live.'],['Fan-out','One update to many receivers.']],
  deep:[{h:'Flow',ul:['Client sends location; server updates cache and publishes.','Subscribers receive; compute distance; push if within range.','On connect, fetch friends\' latest locations from cache.']},
   {h:'Scaling pub/sub',ul:['Shard channels across many Redis nodes with consistent hashing.','About 10M users x 400 friends of subscriptions; most friends offline.','Memory and CPU sizing for messages per second.']},
   {h:'Connections',ul:['Stateful WebSocket servers; reconnect handling.','Subscribe or unsubscribe as friends come online or go offline.']},
   {h:'Privacy',ul:['Opt-in, per-friend sharing controls.','Approximate distances.']}],
  iq:[{q:'Design nearby friends for a small app.',lvl:'Mid',cover:['Location updates, cache, distance check.','Polling vs push.'],pitfalls:['Database writes for every update with no cache.']},
   {q:'Scale the pub/sub layer for 10 million concurrent users.',cover:['Sharded channels; capacity math.','Subscription management; failure of a pub/sub node.'],pitfalls:['One Redis instance.']},
   {q:'Extend to "show random nearby people" (not friends). What changes?',lvl:'Staff+',cover:['Geospatial channels per cell; subscribe to nearby cells.','Cell sizes and moving between cells.','Privacy and abuse controls.'],pitfalls:['Global broadcast.']}]});

P(11,{key:'Design a Hotel Reservation System',short:'Hotel Reservations',
  lead:'Design a hotel chain\'s reservation system: show room-type availability, book rooms for date ranges without double booking (with some overbooking allowed), and handle payments and cancellations. Square asked a hotel booking system per a Blind report.',
  more:['Inventory is counted per hotel, room type and date (not per physical room until check-in). A booking decrements the count for each night atomically, with a constraint that it stays within capacity (plus an overbooking margin). Concurrency control can be pessimistic locks, optimistic version checks, or a database constraint. Idempotency prevents double bookings from retries; the scale is modest, so a relational database sharded by hotel works well.'],
  clarify:[['Scale?','5,000 hotels, 1 million rooms; booking traffic is modest.'],['Overbooking?','Allow 10% for some room types.'],['Booking by room type or exact room?','Room type.'],['Cancellations and pricing?','Yes; dynamic pricing out of scope.']],
  est:{dau:3e6,writes:0.02,ratio:30,size:1000,years:3,peak:5,wlabel:'reservations',rlabel:'availability reads',unit:'reservation'},
  build:B(['Inventory table per (hotel, room type, date) with total and reserved | Atomic per-night counting.','Atomic reservation across all nights in one transaction | No partial bookings.','Constraint or version check: reserved <= total x 1.1 | Overbooking limit enforced.','Idempotency key on reservation requests | No duplicates from double clicks.','Relational DB sharded by hotel | Transactions within one hotel.','Cache for availability browsing | Read-heavy searching.'],['Eventual consistency for inventory counts | Double bookings.','A row per physical room per night with search-time assignment for every query | Unneeded complexity at booking.','Global distributed transactions across hotels | Bookings are per hotel.']),
  takeaway:'Count inventory per hotel, room type and night; reserve all nights atomically with a capacity constraint; make requests idempotent; shard by hotel.',
  pre:['ACID Transactions','Idempotency','Database Sharding'],
  quiz:[{q:'Why model inventory as counts per room type and date?',o:['It is smaller','Guests book a type; counts make availability checks and atomic decrements simple','Rooms do not exist'],a:1,why:'Assign specific rooms at check-in.',hint:'What does the guest choose?'},
        {q:'How do you enforce the overbooking limit under concurrency?',o:['Check in the app','A conditional update or check constraint: reserved + n <= total x 1.1, in a transaction','Nightly batch'],a:1,why:'Atomic enforcement in the database.',hint:'Same as overselling.'}],
  terms:[['Room type inventory','Count of rooms of a type per night.'],['Overbooking','Selling slightly more than capacity, expecting cancellations.'],['Optimistic locking','Update only if the version is unchanged.']],
  deep:[{h:'Data model',ul:['hotels, room_types, room_type_inventory(hotel, type, date, total, reserved).','reservations(id, guest, hotel, type, start, end, status, idempotency key).']},
   {h:'Booking',ul:['Begin; for each night update reserved where reserved + 1 <= limit; check rows affected; insert reservation; commit.','Retry on conflict; idempotency on retries.','Payment authorisation after hold.']},
   {h:'Concurrency options',ul:['Pessimistic: SELECT FOR UPDATE on inventory rows.','Optimistic: version column.','Constraint-based: CHECK on reserved.']},
   {h:'Scale',ul:['Shard by hotel; all of a booking stays on one shard.','Cache availability; re-check at booking.']}],
  iq:[{q:'Design the data model and booking transaction.',lvl:'Mid',cover:['Inventory per night; atomic decrements.','Reservation record; idempotency.'],pitfalls:['Checking availability then inserting without a lock.']},
   {q:'Compare pessimistic, optimistic and constraint-based concurrency here.',cover:['Behaviour under contention.','Retries and user experience.','Which to choose for this load.'],pitfalls:['Not knowing the trade-offs.']},
   {q:'Integrate with online travel agencies that also sell your inventory.',lvl:'Staff+',cover:['Channel manager distributing availability; allotments per channel.','Webhooks and sync; conflict resolution.','Overbooking policy across channels.'],pitfalls:['Treating external channels as always consistent.']}]});

P(11,{key:'Design a Distributed Email Service',short:'Email Service',
  lead:'Design a large email service like Gmail: send and receive mail via SMTP, store mailboxes for hundreds of millions of users, search mail, filter spam, and sync clients.',
  more:['Incoming mail arrives at SMTP servers, passes spam and virus checks, and is stored in the recipient\'s mailbox: metadata (sender, subject, labels, thread) in a wide-column store partitioned by user, bodies and attachments in object storage. Outgoing mail queues for delivery with retries and reputation management (SPF, DKIM, DMARC). Search uses a per-user inverted index. Clients sync over HTTP or IMAP with change notifications.'],
  clarify:[['Scale?','1 billion users, 100 emails received per user per day.'],['Features?','Send, receive, folders/labels, search, attachments.'],['Storage per user?','15 GB quota.'],['Spam filtering?','Yes.']],
  est:{dau:1e9,writes:100,ratio:2,size:50e3,years:5,peak:2,wlabel:'emails received',rlabel:'email reads',unit:'email'},
  build:B(['SMTP inbound servers with spam and virus filtering | Accept and screen mail.','Metadata store partitioned by user (wide-column) | Mailboxes at scale.','Object storage for bodies and attachments | Large blobs.','Per-user search index | Fast mailbox search.','Outbound queue with retries and reputation (SPF/DKIM/DMARC) | Reliable, trusted delivery.','Sync service with push notifications | Clients stay up to date.'],['One relational database for all mailboxes | Size and write volume.','Global search index across all users\' mail | Privacy and scale; per-user indexes fit.','Sending synchronously from the API | Remote servers can be slow or down.']),
  takeaway:'SMTP in and out through queues with filtering and reputation, mailboxes partitioned by user with blobs in object storage, per-user search, and sync with notifications.',
  pre:['Message Queues','Database Partitioning','Design Notification Service'],
  quiz:[{q:'Why partition mailbox data by user?',o:['For billing','Almost every query is about one user\'s mailbox, so keeping it together makes reads local','Users demand it'],a:1,why:'Locality for the dominant access pattern.',hint:'Access pattern.'},
        {q:'Why does outbound mail go through a queue?',o:['To delay it','Recipient servers may be slow or temporarily reject mail; queues allow retries over hours','Queues encrypt mail'],a:1,why:'SMTP delivery is unreliable by nature.',hint:'Remote servers.'}],
  terms:[['SMTP','Protocol for sending email between servers.'],['DKIM','Signature proving a domain sent the mail.'],['Thread','Messages grouped by conversation.']],
  deep:[{h:'Receiving',ul:['MX records route to inbound SMTP servers.','Filters: spam ML, virus scanning, authentication checks.','Store metadata and body; update index; notify clients.']},
   {h:'Sending',ul:['API accepts; store in Sent; queue for delivery.','Workers deliver via SMTP with retries and backoff.','Bounce handling; IP reputation and rate control.']},
   {h:'Storage and search',ul:['Metadata rows by (user, label, time).','Attachments deduplicated by hash.','Per-user index updated asynchronously.']},
   {h:'Sync',ul:['Change log per mailbox; clients sync by history id.','Push via WebSocket or mobile push.']}],
  iq:[{q:'Design receiving and storing an email.',lvl:'Mid',cover:['SMTP, filters, storage split.','Notifications.'],pitfalls:['Storing attachments in the database.']},
   {q:'Design mailbox search for 1 billion users.',cover:['Per-user inverted indexes; sharded with mailboxes.','Async indexing; ranking by recency.','Cost and storage.'],pitfalls:['One global index.']},
   {q:'Your outbound IPs are being blocked as spam by major providers. Diagnose and fix.',lvl:'Staff+',cover:['Check authentication (SPF, DKIM, DMARC), complaint rates, compromised accounts sending spam.','Outbound spam detection and rate limits per user.','IP pools by reputation; warm-up; feedback loops with providers.'],pitfalls:['Rotating IPs without fixing the cause.']}]});
tagTier(11,'Medium');
